import type { Locale } from "@/i18n/config";
import commons from "../../../public/images/festivals/commons.json";

// ─────────────────────────────────────────────────────────
//  A photograph for every festival.
//
//  Generated by scripts/images/fetch-commons.mjs, which asks the
//  Commons API for each file's real licence and author and refuses
//  anything not freely licensed. The credits below are whatever
//  Commons actually returned, not what anyone typed here.
//
//  Alt text is written by hand, because a manifest cannot carry it
//  and because alt text describing the wrong thing is worse than
//  none. Each one says what is in the frame, not what the festival
//  means.
// ─────────────────────────────────────────────────────────

export interface FestivalImage {
  src: string;
  width: number;
  height: number;
  credit: string;
  sourceUrl: string;
  alt: Record<Locale, string>;
  /** Which part of the frame to keep when a hero crops it. */
  position?: string;
}

