type Entry = { src: string; width: number; height: number; credit: string; sourceUrl: string };
const FROM_COMMONS = commons as Record<string, Entry>;

const IMAGES: Record<string, FestivalImage> = {};
for (const [id, entry] of Object.entries(FROM_COMMONS)) {
  const alt = ALT[id];
  // No alt text written means the picture is not used. A photograph
  // with no description is not an improvement on no photograph.
  if (!alt) continue;
  IMAGES[id] = { ...entry, alt, position: "50% 50%" };
}

export function festivalImage(slug: string): FestivalImage | undefined {
  return IMAGES[slug];
}

export function allFestivalImages(): [string, FestivalImage][] {
  return Object.entries(IMAGES);
}
